/* Integer Promotions & Unsigned Pitfalls */

int i = -1;
unsigned int u = 1;

// Pitfall: i promoted to unsigned (UINT_MAX)
// (UINT_MAX > 1) is TRUE
if (i > u) {
    // This branch executes!
}

size_t sz = 5;
int count = -10;

// Warning: Comparison between signed/unsigned
// count implicitly converts to large size_t
if (count < sz) {
    // Expected: TRUE (since -10 < 5)
    // Actual: FALSE (since size_t(-10) is huge)
}
